// Uploads the built artifact to the release bucket.
const fs = require("fs");
const http = require("http");
const https = require("https");
const { URL } = require("url");

// The release bucket name is not recorded in this repo; it is supplied at
// release time via RELEASE_BUCKET (e.g. "my-bucket" or a full endpoint such as
// "https://storage.example.com/my-bucket").
const BUCKET = process.env.RELEASE_BUCKET || "";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

// Resolve the full URL of the object to PUT. BUCKET may be a bare bucket
// name (in which case the host is taken from ENDPOINT) or a full URL.
function objectUrl(bucket, name) {
  if (/^https?:\/\//i.test(bucket)) {
    const u = new URL(bucket);
    u.pathname = `${u.pathname.replace(/\/$/, "")}/${encodeURIComponent(name)}`;
    return u;
  }
  const endpoint =
    process.env.ENDPOINT || "https://storage.googleapis.com";
  const u = new URL(endpoint);
  u.pathname = `/${encodeURIComponent(bucket)}/${encodeURIComponent(name)}`;
  return u;
}

function put(url, body) {
  return new Promise((resolve, reject) => {
    const lib = url.protocol === "https:" ? https : http;
    const req = lib.request(
      url,
      {
        method: "PUT",
        headers: {
          "Content-Type": "application/javascript",
          "Content-Length": body.length,
          ...(process.env.API_KEY
            ? { Authorization: `Bearer ${process.env.API_KEY}` }
            : {}),
        },
      },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () => {
          const text = Buffer.concat(chunks).toString("utf8");
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({ statusCode: res.statusCode, body: text });
          } else {
            reject(
              new Error(
                `PUT ${url.href} failed: HTTP ${res.statusCode}\n${text}`
              )
            );
          }
        });
      }
    );
    req.on("error", reject);
    req.end(body);
  });
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error(
      "BUCKET is not set; supply the release bucket via RELEASE_BUCKET"
    );
  }
  const url = objectUrl(BUCKET, name);
  const res = await put(url, body);
  console.log(
    `uploaded ${name} (${body.length} bytes) to ${BUCKET} ` +
      `(HTTP ${res.statusCode})`
  );
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
